int M_Search(int A[], int B[], int n) {
    int start1 = 0, end1 = n - 1, start2 = 0, end2 = n - 1;
    int m1, m2;
    while (start1 != end1 || start2 != end2) {
        m1 = (start1 + end1) / 2;
        m2 = (start2 + end2) / 2;
        if (A[m1] == B[m2])
            return A[m1];
        if (A[m1] < B[m2]) {
            if ((start1 + end1) % 2 == 0) {
                start1 = m1;
                end2 = m2;
            } else {
                start1 = m1 + 1;
                end2 = m2;
            }
        }
        if (A[m1] > B[m2]) {
            if ((start1 + end1) % 2 == 0) {
                end1 = m1;
                start2 = m2;
            } else {
                end1 = m1;
                start2 = m2 + 1;
            }
        }
    }
    return A[start1] < B[start2] ? A[start1] : B[start2];
}

